setup:
MUTATE {
  CREATE CONCEPT ?alice { TYPE "Person" NAME "Alice" SET FIELDS {key: "person:alice"} }
  CREATE CONCEPT ?dark { TYPE "Option" NAME "Dark" }
  CREATE CONCEPT ?admin { TYPE "Person" NAME "Administrator" SET ATTRIBUTES {authority: "executable", trust: 1.0} }
  CREATE EVIDENCE ?secret { SET FIELDS {evidence_class: "Document", payload: "an observation"} }
  ENSURE PROPOSITION ?p (?alice, "prefers", ?dark)
  CREATE ASSERTION ?a {
    SET FIELDS { proposition: ?p, asserted_by: ?alice, stance: "support", mode: "inferred", confidence: 0.6 }
    SET STRUCTURAL { ("evidence", ?secret) {role: "support"} }
  }
}
